/// <summary>
/// Computes an identity automorphism (i.e. a self-mapping of a graph in which each vertex also maps to itself).
/// </summary>
/// <typeparam name="V">The graph vertex type.</typeparam>
/// <typeparam name="E">The graph edge type.</typeparam>
/// <param name="graph">The input graph.</param>
/// <returns>A mapping from graph to graph.</returns>
public static IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph)
{
    // Create a new map to store the mapping from vertices to themselves
    Map<V,V> vertexMapping = new HashMap<>();
    // Loop over all vertices in the graph
    for (V vertex : graph.getVertices())
    {
        // Add the vertex to the mapping, where it maps to itself
        vertexMapping.put(vertex, vertex);
    }
    // Return the mapping as an IsomorphicGraphMapping object
    return new IsomorphicGraphMapping<V,E>(graph, vertexMapping);
}

// This method computes an identity automorphism for a graph.
// The input graph is passed as a parameter, and the output mapping is returned as a new IsomorphicGraphMapping object.

<V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {

  // Create a new IsomorphicGraphMapping object to store the identity mapping
  IsomorphicGraphMapping<V, E> mapping = new IsomorphicGraphMapping<V, E>(graph);

  // Loop through each vertex in the graph
  for (V vertex : graph.vertices()) {

    // Create a new mapping from the vertex to itself
    mapping.map(vertex, vertex);
  }

  // Return the computed mapping
  return mapping;
}

