public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Initialize the vertex set of the graph
    Set<V> vertices = new HashSet<>();
    for (String clazz : resultMap.keySet()) {
        vertices.add(resultMap.get(clazz));
    }
    // Add vertices to the graph
    for (V vertex : vertices) {
        target.addVertex(vertex);
    }
    // Add edges to the graph
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1.equals(vertex2)) {
                continue;
            }
            Edge<E> edge = new Edge<>(vertex1, vertex2, null);
            target.addEdge(edge);
        }
    }
}

/**
 * Construct a complete bipartite graph
 */
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Set up the two disjoint sets
    Set<V> leftSet = new HashSet<>();
    Set<V> rightSet = new HashSet<>();

    // Iterate over all elements in the result map
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        // If the value is in the left side, add it to the left set
        if (entry.getValue().isInLeft()) {
            leftSet.add(entry.getValue());
        } else { // If the value is in the right side, add it to the right set
            rightSet.add(entry.getValue());
        }
    }

    // Create the edges between the sets
    for (V left : leftSet) {
        for (V right : rightSet) {
            E edge = target.addEdge(left, right);
            if (edge == null) {
                // If the edge could not be added, remove the vertex from the left set
                leftSet.remove(left);
            }
        }
    }

    // Add the vertices to the graph
    target.addVertices(leftSet);
    target.addVertices(rightSet);
}

