  public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
      return null;
    }

    TypeVariable<Class<?>>[] typeVars = targetType.getTypeParameters();
    ParameterizedType paramType = (ParameterizedType) genericType;
    Class<?>[] rawTypes = paramType.getActualTypeArguments();

    List<Class<?>> argTypes = new ArrayList<>();
    for (Type rawType : rawTypes) {
      if (rawType instanceof Class) {
        argTypes.add((Class<?>) rawType);
        continue;
      }

      if (rawType instanceof GenericArrayType) {
        GenericArrayType arrayType = (GenericArrayType) rawType;
        Class<?> elemType = (Class<?>) arrayType.getGenericComponentType();
        argTypes.add(elemType);
        continue;
