      if (rawType instanceof TypeVariable) {
        String typeVarName = ((TypeVariable) rawType).getName();
        for (TypeVariable<Class<?>> typeVar : typeVars) {
          if (typeVar.getName().equals(typeVarName)) {
            argTypes.add(typeVar.getBounds()[0]);
            break;
          }
        }
      }
    }

    return argTypes.toArray(new Class[0]);
  }
}

