/**
 * Computes the size of the utf8 string beginning at the specified {@code index} with the specified {@code length}.
 */
public static int computeUTF8Size(final CharSequence str, final int index,final int len){

    int size = 0;
    final int end = index + len;

    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if (c > 0 && c < 128) {
            size++;
        } else if (c < 0x800) {
            size += 2;
        } else {
            size += 3;
        }
    }
    return size;

}

public static int computeUTF8Size(@NotNull final CharSequence str, final int index, final int len) {
    // Check if the parameters are valid
    if (str == null) throw new NullPointerException("str cannot be null");
    if (index < 0 || index >= str.length()) throw new IndexOutOfBoundsException("index is out of bounds: " + index);
    if (len < 0 || index + len > str.length()) throw new IllegalArgumentException("len is out of bounds: " + len);

    int size = 0;

    // Iterate over the characters in the string
    for (int i = index; i < index + len; i++) {
        final char ch = str.charAt(i);

        // If the character is in the Basic Multilingual Plane (BMP), add 1 byte
        if (ch <= 0x007F) {
            size++;
        }
        // If the character is in the Supplementary Planes (SP), add 3 bytes
        else {
            size += 3;
        }
    }

    return size;
}

