import org.atmosphere.cpr.AtmosphereResource;
import org.atmosphere.handler.RefusalException;
import org.atmosphere.handler.SuspendProcessor;

public class AutoSuspendProcessor implements SuspendProcessor {
  @Override
  public Action inspect(AtmosphereResource r) {
    if (r.transport() == AtmosphereResource.TRANSPORT.WEBSOCKET) {
      return Action.CONTINUE;
    }

    boolean suspend = r.transport() == AtmosphereResource.TRANSPORT.WEBSOCKET;

    if (!suspend) {
      throw new RefusalException("SuspendProcessor", "Suspend connection");
    }

    return Action.SUSPEND;
  }
