        // Get the start and end vertices of the edge
        V start = edge.getStart();
        V end = edge.getEnd();

        // Add the edge to the path
        path.addEdge(edge);

        // Add the vertices to the path
        path.addVertex(start);
        path.addVertex(end);

        // If the start vertex is not the end vertex, add its neighbors to the stack
        if (!start.equals(end)) {
            edgeStack.addAll(graph.getNeighbors(start));
        }
    }

    // Return the path
    return path;
