public List<SequenceRange> buildSequenceRanges() {

// Step 1: Get the current profiles segment
List<Profile> profilesSegment = getCurrentProfilesSegment();

// Step 2: Sort the profiles by their sequence number
profilesSegment.sort(Comparator.comparingInt(Profile::getSequenceNumber));

// Step 3: Build the sequence ranges
List<SequenceRange> sequenceRanges = new ArrayList<>();
for (int i = 0; i < profilesSegment.size(); i++) {
    Profile profile = profilesSegment.get(i);
    int sequenceNumber = profile.getSequenceNumber();
    int searchRangeStart = sequenceNumber - SEARCH_RANGE_SIZE;
    int searchRangeEnd = sequenceNumber + SEARCH_RANGE_SIZE;
    if (i > 0) {
        Profile previousProfile = profilesSegment.get(i - 1);
        if (previousProfile.getSequenceNumber() == searchRangeStart - 1) {
            searchRangeStart++;
        }
    }
    if (i < profilesSegment.size() - 1) {
        Profile nextProfile = profilesSegment.get(i + 1);
        if (nextProfile.getSequenceNumber() == searchRangeEnd + 1) {
            searchRangeEnd--;
        }
    }
    sequenceRanges.add(new SequenceRange(searchRangeStart, searchRangeEnd));
}

return sequenceRanges;
}

